pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, address user2, uint256 amount1, uint256 amount2) public {
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != user2);
        amount1 = bound(amount1, 1, 100 ether);
        amount2 = bound(amount2, 1, 100 ether);

        // Deposit from user1
        vm.deal(user1, amount1);
        vm.prank(user1);
        c.deposit{value: amount1}();

        // Deposit from user2
        vm.deal(user2, amount2);
        vm.prank(user2);
        c.deposit{value: amount2}();

        // user1 withdraws all
        vm.prank(user1);
        c.withdrawAll();

        // The general rule: contract balance equals sum of credits
        uint256 totalCredits = c.credit(user1) + c.credit(user2);
        uint256 contractBalance = address(c).balance;
        assertTrue(totalCredits == contractBalance);
    }
}

